// PF-10 · Clasificar mensaje (Run Once for All Items). Único nodo que lee el Update de Telegram.
// Devuelve {tipo, chat_id, telefono}; nunca copia el texto del cliente.

// Igual en Clasificar mensaje y en Filtrar por teléfono.
function normalizarTelefono(valor) {
  if (typeof valor !== 'string') return null;
  const texto = valor.trim();
  if (texto === '' || !/^\+?[\d\s.\-()]+$/.test(texto)) return null;
  const digitos = texto.replace(/\D/g, '');
  let e164 = null;
  if (texto.startsWith('+')) e164 = '+' + digitos;
  else if (digitos.startsWith('00')) e164 = '+' + digitos.slice(2);
  else if (digitos.length === 9) e164 = /^[67]/.test(digitos) ? '+34' + digitos : null;
  else if (digitos.length > 9) e164 = '+' + digitos;
  if (e164 === null) return null;
  const numero = e164.slice(1);
  if (!/^[1-9]\d{7,14}$/.test(numero)) return null;
  if (numero.startsWith('34') && numero.length !== 11) return null;
  return e164;
}

function clasificar(update) {
  const m = update && update.message;
  if (!m || !m.chat || !Number.isSafeInteger(m.chat.id)) return null;
  const chat_id = m.chat.id;
  if (m.chat.type !== 'private') return { tipo: 'grupo', chat_id, telefono: null };
  if (m.contact) {
    const userId = m.contact.user_id;
    const fromId = m.from && m.from.id;
    const propio = Number.isSafeInteger(userId) && Number.isSafeInteger(fromId) && userId === fromId;
    if (!propio) return { tipo: 'contacto_ajeno', chat_id, telefono: null };
    const telefono = normalizarTelefono(m.contact.phone_number);
    return telefono
      ? { tipo: 'contacto_valido', chat_id, telefono }
      : { tipo: 'telefono_no_valido', chat_id, telefono: null };
  }
  const texto = typeof m.text === 'string' ? m.text.trim() : '';
  if (/^\/(start|saldo)(@\w+)?(\s|$)/i.test(texto)) return { tipo: 'inicio', chat_id, telefono: null };
  return { tipo: 'no_entendido', chat_id, telefono: null };
}

const resultado = clasificar($input.first().json);
return resultado ? [{ json: resultado }] : [];

// PF-10 · Filtrar por teléfono (Run Once for All Items).
// Entrada: los apartados activos de la API, o un item vacío si la lista llega vacía (Always Output Data).
// Devuelve un solo item {chat_id, tipo, apartados}; tipo es saldo, no_encontrado o identidad_dudosa.

// Igual en Clasificar mensaje y en Filtrar por teléfono.
function normalizarTelefono(valor) {
  if (typeof valor !== 'string') return null;
  const texto = valor.trim();
  if (texto === '' || !/^\+?[\d\s.\-()]+$/.test(texto)) return null;
  const digitos = texto.replace(/\D/g, '');
  let e164 = null;
  if (texto.startsWith('+')) e164 = '+' + digitos;
  else if (digitos.startsWith('00')) e164 = '+' + digitos.slice(2);
  else if (digitos.length === 9) e164 = /^[67]/.test(digitos) ? '+34' + digitos : null;
  else if (digitos.length > 9) e164 = '+' + digitos;
  if (e164 === null) return null;
  const numero = e164.slice(1);
  if (!/^[1-9]\d{7,14}$/.test(numero)) return null;
  if (numero.startsWith('34') && numero.length !== 11) return null;
  return e164;
}

function nombreComparable(nombre) {
  return typeof nombre === 'string' ? nombre.trim().replace(/\s+/g, ' ').toLowerCase() : '';
}

function filtrar(apartados, telefono) {
  if (typeof telefono !== 'string') return { tipo: 'no_encontrado', apartados: [] };
  const propios = apartados.filter((a) =>
    a && Number.isSafeInteger(a.id) && a.estado === 'activo' && normalizarTelefono(a.telefono) === telefono);
  if (propios.length === 0) return { tipo: 'no_encontrado', apartados: [] };
  if (new Set(propios.map((a) => nombreComparable(a.cliente))).size > 1) return { tipo: 'identidad_dudosa', apartados: [] };
  // Solo lo que necesita Redactar respuesta: ni nombre, ni teléfono, ni id.
  return {
    tipo: 'saldo',
    apartados: propios.map((a) => ({ producto: a.producto, talla: a.talla, pendiente: a.pendiente, fecha_limite: a.fecha_limite })),
  };
}

const { chat_id, telefono } = $('Clasificar mensaje').first().json;
return [{ json: { chat_id, ...filtrar($input.all().map((item) => item.json), telefono) } }];

// PF-10 · Redactar respuesta (Run Once for All Items).
// Llega desde Decidir respuesta (inicio, no_entendido, contacto_ajeno, telefono_no_valido)
// o desde Filtrar por teléfono (saldo, no_encontrado, identidad_dudosa). Devuelve {chat_id, texto}.
// Los importes y las fechas se muestran tal como los da la app: sin sumar, sin redondear, sin new Date().

const escapar = (t) => t == null ? '' : String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// contacto_html llega ya escapado de Leer configuración: se usa tal cual.
function contactoTexto(c) {
  return typeof c === 'string' && c.trim() !== '' ? c : 'la tienda';
}

// Euros de la API (número con hasta dos decimales) a céntimos enteros, sin coma flotante.
function centimos(valor) {
  if (typeof valor !== 'number') return null;
  const texto = String(valor);
  if (!/^\d+(\.\d{1,2})?$/.test(texto)) return null;
  const [enteros, decimales = ''] = texto.split('.');
  return Number(enteros) * 100 + Number(decimales.padEnd(2, '0'));
}

function importe(c) {
  const euros = String(Math.floor(c / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return `${euros},${String(c % 100).padStart(2, '0')} €`;
}

// AAAA-MM-DD a DD/MM/AAAA partiendo el texto.
function fecha(iso) {
  const m = typeof iso === 'string' ? /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso) : null;
  return m ? `${m[3]}/${m[2]}/${m[1]}` : null;
}

function redactar(tipo, apartados, contactoHtml, hoy) {
  const contacto = contactoTexto(contactoHtml);
  const derivar = `No puedo mostrarte estos datos por aquí. Habla con ${contacto} y lo revisamos.`;
  switch (tipo) {
    case 'inicio':
      return 'Hola. Para ver lo que te falta por pagar, pulsa «Consultar mi saldo» y comparte tu contacto. Solo usamos tu número para buscar tus apartados en esta consulta.';
    case 'no_entendido':
      return `No he entendido tu mensaje. Para consultar tu saldo, pulsa «Consultar mi saldo». Para cualquier otra cosa, habla con ${contacto}.`;
    case 'contacto_ajeno':
      return 'Solo puedo consultar tu propio número. Pulsa «Consultar mi saldo» para compartir tu contacto.';
    case 'telefono_no_valido':
    case 'no_encontrado':
      return `No encuentro apartados pendientes con tu número. Si crees que es un error, habla con ${contacto}.`;
    case 'identidad_dudosa':
      return derivar;
    case 'saldo': {
      const lineas = [];
      for (const a of apartados) {
        const c = centimos(a.pendiente);
        const limite = fecha(a.fecha_limite);
        const producto = typeof a.producto === 'string' ? a.producto.trim() : '';
        // Un dato que no encaja invalida toda la respuesta: un saldo parcial es peor que derivar.
        if (c === null || limite === null || producto === '') return derivar;
        const talla = a.talla == null || String(a.talla).trim() === '' ? '' : ` (talla ${escapar(a.talla)})`;
        const vencido = hoy > a.fecha_limite ? ` El plazo ya ha pasado: habla con ${contacto}.` : '';
        lineas.push(`- ${escapar(producto)}${talla}: te faltan ${importe(c)}. Fecha límite: ${limite}.${vencido}`);
      }
      if (lineas.length === 0) return derivar;
      return `Tus apartados pendientes:\n${lineas.join('\n')}\nSi tienes dudas, habla con ${contacto}.`;
    }
    default:
      throw new Error('Tipo de respuesta no previsto');
  }
}

const clasificacion = $('Clasificar mensaje').first().json;
const filtrado = $('Filtrar por teléfono').isExecuted ? $('Filtrar por teléfono').first().json : null;
const contactoHtml = $('Leer configuración').first().json.contacto_html;
const hoy = $now.setZone('Europe/Madrid').toISODate();
const { tipo, apartados } = filtrado || { tipo: clasificacion.tipo, apartados: [] };
return [{ json: { chat_id: clasificacion.chat_id, texto: redactar(tipo, apartados, contactoHtml, hoy) } }];

// PF-10 · Redactar aviso de fallo (Run Once for All Items).
// Llega por la salida de error de Leer configuración o de Consultar apartados activos.
// Devuelve un solo item {chat_id, texto, origen}; nunca copia el error ni datos del cliente.

// contacto_html llega ya escapado de Leer configuración: se usa tal cual.
function contactoTexto(c) {
  return typeof c === 'string' && c.trim() !== '' ? c : 'la tienda';
}

function redactarAviso(contactoHtml, apiEjecutada) {
  return {
    texto: `Ahora mismo no puedo consultar tu saldo. Inténtalo más tarde o habla con ${contactoTexto(contactoHtml)}.`,
    origen: apiEjecutada ? 'API' : 'configuración',
  };
}

// first(0): la salida Success de Leer configuración. Sin índice, n8n lee la salida conectada a este
// nodo, que es la de Error y está vacía cuando lo que falla es la API.
let contactoHtml;
try {
  contactoHtml = $('Leer configuración').first(0)?.json?.contacto_html;
} catch (e) {
  contactoHtml = undefined;
}
const { chat_id } = $('Clasificar mensaje').first().json;
return [{ json: { chat_id, ...redactarAviso(contactoHtml, $('Consultar apartados activos').isExecuted) } }];
